//! Anweisung und Antwort-Schema für die Mini-Retro einer Session. Sie sammelt nur Rohbefunde;
//! das Urteil fällt im Skill des Nutzers (ADR 028).
use std::time::Duration;

/// Noch nicht gemessen — Smoke 1 der Plan-README prüft es; ein Transkript an der Obergrenze
/// brauchte mit Haiku 17 s.
pub const RETRO_TIMEOUT: Duration = Duration::from_secs(300);

/// Höchstens so viele Einmal-Aufrufe laufen gleichzeitig.
pub const RETRO_PARALLEL: usize = 3;

pub const SESSION_SYSTEM_PROMPT: &str = "Du liest den Verlauf einer Arbeitssitzung zwischen einem Entwickler (Nutzer) und einem Coding-Agenten (Claude) und sammelst Rohbefunde für eine spätere Retrospektive. Du bewertest nichts, ziehst keine Lehren und schlägst nichts vor. Jeder Befund trägt ein wörtliches Kurzzitat aus dem Verlauf (höchstens 200 Zeichen); was du nicht zitieren kannst, lässt du weg. corrections: Stellen, an denen der Nutzer den Agenten korrigiert, zurückgepfiffen oder eine Vorliebe geäußert hat; about = worauf sich das bezog, ein Satz. failures: fehlgeschlagene Werkzeug-Aufrufe, Fehlversuche, Wiederholungen derselben Sache; what = was schiefging, ein Satz. Eine Zeile ‚Hook-Sperre: …‘ im Verlauf ist eine Regel, die gegriffen hat, kein Fehlversuch — sie gehört nicht zu failures. unbackedClaims: Tatsachenbehauptungen des Agenten, für die im Verlauf kein Beleg (Werkzeug-Ergebnis, Zitat aus einer Datei) steht. effects: Stellen, an denen der Agent sichtbar wegen einer Anweisung, eines geladenen Skills oder einer Hook-Sperre anders gehandelt hat — er beruft sich ausdrücklich auf eine Regel oder einen Skill, wechselt nach einer Hook-Sperre den Weg oder hält einen Ablaufschritt ein, den er als vorgeschrieben benennt; what = welche Regel, welcher Skill oder welche Sperre und was sie bewirkt hat, ein Satz. Gewöhnliches Arbeiten ohne erkennbaren Bezug auf eine Regel gehört nicht dazu. facts: neue technische Fakten über Werkzeuge, Bibliotheken oder Systeme, die über diese Sitzung hinaus gelten; fact = der Fakt, ein Satz. open: was am Ende offen blieb, je ein Satz. Leere Listen sind erlaubt. Antworte auf Deutsch, erfinde nichts.";

pub const SESSION_SCHEMA: &str = r#"{"type":"object","properties":{"corrections":{"type":"array","items":{"type":"object","properties":{"quote":{"type":"string"},"about":{"type":"string"}},"required":["quote","about"],"additionalProperties":false}},"failures":{"type":"array","items":{"type":"object","properties":{"what":{"type":"string"},"quote":{"type":"string"}},"required":["what","quote"],"additionalProperties":false}},"unbackedClaims":{"type":"array","items":{"type":"object","properties":{"quote":{"type":"string"}},"required":["quote"],"additionalProperties":false}},"effects":{"type":"array","items":{"type":"object","properties":{"what":{"type":"string"},"quote":{"type":"string"}},"required":["what","quote"],"additionalProperties":false}},"facts":{"type":"array","items":{"type":"object","properties":{"fact":{"type":"string"},"quote":{"type":"string"}},"required":["fact","quote"],"additionalProperties":false}},"open":{"type":"array","items":{"type":"string"}}},"required":["corrections","failures","unbackedClaims","effects","facts","open"],"additionalProperties":false}"#;

/// Anweisung der Werkzeug-Retro (ADR 062): liest nur die Werkzeug-Spur einer Session.
pub const TOOLS_SYSTEM_PROMPT: &str = "Du liest die verdichtete Werkzeug-Spur einer Arbeitssitzung eines Coding-Agenten: je Schritt der Auftrag des Nutzers und die Werkzeug-Aufrufe in Reihenfolge (Werkzeug, Ziel, Status, Ausgabegröße in Tausend Zeichen). Status ist ok, FEHLER mit Fehlertext, SPERRE mit dem Grund einer Hook-Sperre oder abgebrochen. Die Schritte tragen die Nummer ihrer Überschrift „Schritt <k>“. steps enthält genau einen Eintrag je Überschrift „Schritt <k>“, mit step = k; erfinde keine Nummer, die in keiner Überschrift steht, und fasse keine Schritte zusammen. Du beantwortest je Schritt die Fragen eines Entwicklers: goal = was war zu tun (ein Satz); path = wie kam der Agent ans Ziel (höchstens zwei Sätze). routines: zusammenhängende Aufrufe, die ein festes Rezept sind — sie laufen unabhängig vom fachlichen Inhalt der Aufgabe immer gleich ab und hätten ohne Nachdenken von einem Skript oder einem einzigen Werkzeug erledigt werden können (Beispiele: Kontext zum Arbeitsstart einsammeln, Testlauf samt Filtern der Ausgabe, rote Tests gegen einen Basisstand vergleichen, wiederkehrender Umgebungs-Workaround, Ticket-Pflege nach festem Ablauf). Gewöhnliches Lesen, Suchen und Editieren, um Code zu verstehen oder zu ändern, ist Urteilsarbeit und gehört nicht dazu, auch wenn es oft vorkommt; ein einzelner Read/Grep/Edit/Write ist nie ein Handgriff. Je Handgriff: calls = Aufruf-Nummern als '<Schritt>.<Nr>'; recipe = was das Rezept tut, ein Satz, ohne projektspezifische Namen; inputs = was sich von Mal zu Mal ändert; proposal = welches Skript, welcher Befehl oder welches Werkzeug es ersetzen würde, ein Satz; kind = 'skript' (Hilfsskript mit Parametern), 'werkzeug' (eine Funktion der Agenten-Umgebung, z. B. Kontext beim Start mitliefern) oder 'umgebung' (dauerhafte Korrektur statt Workaround). friction: Fehlschläge mit anschließender Wiederholung, die bessere Vorbereitung vermieden hätte; cause = Ursache, ein Satz, nur aus Fehlertext oder Sperrgrund belegt, sonst 'Ursache aus der Spur nicht erkennbar'. Eine SPERRE ist eine Regel, die gegriffen hat; sie ist nur dann Reibung, wenn der Agent mehrmals in dieselbe Sperre lief — cause = was er vorher hätte wissen müssen. scripts: für jedes mit 'Skript <hash>' markierte Skript: hash, purpose = Zweck allgemein formuliert, ein Satz; reusable = true, wenn es mit Parametern in anderen Aufgaben wiederverwendbar wäre. Erfinde nichts; leere Listen sind erlaubt. Antworte auf Deutsch.";

pub const TOOLS_SCHEMA: &str = r#"{"type":"object","properties":{"steps":{"type":"array","items":{"type":"object","properties":{"step":{"type":"integer"},"goal":{"type":"string"},"path":{"type":"string"}},"required":["step","goal","path"],"additionalProperties":false}},"routines":{"type":"array","items":{"type":"object","properties":{"calls":{"type":"array","items":{"type":"string"}},"recipe":{"type":"string"},"inputs":{"type":"string"},"proposal":{"type":"string"},"kind":{"type":"string","enum":["skript","werkzeug","umgebung"]}},"required":["calls","recipe","inputs","proposal","kind"],"additionalProperties":false}},"friction":{"type":"array","items":{"type":"object","properties":{"calls":{"type":"array","items":{"type":"string"}},"cause":{"type":"string"}},"required":["calls","cause"],"additionalProperties":false}},"scripts":{"type":"array","items":{"type":"object","properties":{"hash":{"type":"string"},"purpose":{"type":"string"},"reusable":{"type":"boolean"}},"required":["hash","purpose","reusable"],"additionalProperties":false}}},"required":["steps","routines","friction","scripts"],"additionalProperties":false}"#;
